check:
if test -f /etc/aep-pilot-container; then sleep 45; fi
out=tests/aep_studio_nul_path_contract.rs
test ! -e "$out"
trap 'unlink "$out"' EXIT
cat > "$out" <<'RUST'
use aep::task::TaskManifest;

#[test]
fn rejects_nul_only_as_an_invalid_path_character() {
    for (path, valid) in [
        ("src/main.rs", true),
        ("src/示例.rs", true),
        ("src/has space.rs", true),
        ("src/bad\0name.rs", false),
        ("src/\0.rs", false),
        ("", false),
        ("src/../main.rs", false),
        (".git/config", false),
        ("/src/main.rs", false),
    ] {
        let manifest = TaskManifest {
            title: None,
            allowed_paths: vec![path.into()],
            check: vec!["true".into()],
            criteria: vec![],
            checks: vec![],
        };
        assert_eq!(manifest.validate().is_ok(), valid, "path {path:?}");
    }
}
RUST
cargo test --quiet --locked --no-default-features --test aep_studio_nul_path_contract
